window.CompanionWorkspaceBundle["designer"]="<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>新的她 · 人格处理</title>\n  <style>@charset \"UTF-8\";\n/* Same workbench variables as the questionnaire; the cottage projects its palette. */\n:root{color-scheme:light;--page:#f5f7f5;--surface:#fff;--surface-muted:#f8faf8;--ink:#293a32;--muted:#61736a;--ink-soft:#8b9a90;--line:#dfe8e0;--line-strong:#cfdccb;--accent:#3f7a5c;--accent-soft:#e4f1e9;--danger:#a94f4a;--r-sm:8px;--r-lg:8px;--gap:12px;--pad:20px;--type-scale:1;font-family:\"MiSans\",\"PingFang SC\",\"Microsoft YaHei\",system-ui,sans-serif;background:var(--page);color:var(--ink)}\n:root[data-radius=\"sharp\"]{--r-sm:4px;--r-lg:7px}:root[data-radius=\"round\"]{--r-sm:14px;--r-lg:22px}\n:root[data-density=\"compact\"]{--gap:8px;--pad:14px}:root[data-density=\"roomy\"]{--gap:16px;--pad:26px}\n:root[data-type-scale=\"s\"]{--type-scale:.94}:root[data-type-scale=\"l\"]{--type-scale:1.08}:root[data-type-scale=\"xl\"]{--type-scale:1.18}\n:root[data-theme=\"night\"]{color-scheme:dark}\n*{box-sizing:border-box}body{margin:0;font-size:calc(14px * var(--type-scale));line-height:1.6}button,input,select,textarea{font:inherit;color:inherit}button{cursor:pointer}button:disabled{cursor:default;opacity:.5}[hidden]{display:none!important}\nh1,h2,h3,p{margin:0}h1{font-size:1.25em;line-height:1.4}h2{font-size:1em}h3{font-size:.95em}small{font-size:.85em}.muted,.memory-note,.footnote{color:var(--muted)}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}\n.designer{max-width:1380px;margin:0 auto;padding:var(--pad)}.workbench-head,.heading,.actions,.section-heading,.composer-foot,.draft-foot,.dialog-heading,.dialog-foot,.mode-row{display:flex;align-items:center;gap:var(--gap)}.workbench-head,.section-heading,.composer-foot,.draft-foot,.dialog-heading,.mode-row{justify-content:space-between}.workbench-head,.mode-row,.composer-foot,.draft-foot,.actions{flex-wrap:wrap}.heading{min-width:0}.heading p{font-size:.9em;margin-top:2px}.mark{display:grid;place-items:center;flex-shrink:0;width:42px;height:42px;border:1px solid var(--line-strong);border-radius:var(--r-sm);background:var(--accent-soft);color:var(--accent);font-size:1.15em;font-weight:600}.actions{gap:6px}\n.button{display:inline-flex;align-items:center;justify-content:center;min-height:36px;padding:7px 13px;border:1px solid var(--line-strong);border-radius:var(--r-sm);background:var(--surface);font-weight:500;line-height:1.4}.button:hover:not(:disabled){border-color:var(--accent);color:var(--accent)}.button.primary{background:var(--accent);border-color:var(--accent);color:var(--surface)}.button.primary:hover:not(:disabled){filter:brightness(.95);color:var(--surface)}.button.small{min-height:32px;padding:6px 10px;font-size:.9em}\n.workbench-head>.actions{min-width:0;max-width:100%}.workbench-head .button{min-width:0;overflow-wrap:anywhere}#choose-model{max-width:240px}\nbutton:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px}textarea,input,select{width:100%;border:1px solid var(--line-strong);border-radius:var(--r-sm);padding:10px 12px;background:var(--surface);outline:none;min-width:0}textarea{display:block;resize:vertical;line-height:1.7;tab-size:2}textarea:focus,input:focus,select:focus{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-soft)}textarea::placeholder{color:var(--ink-soft)}textarea:disabled{background:var(--surface-muted);color:var(--muted)}\n.mode-row{margin:20px 0 14px}.mode-switch{display:inline-flex;gap:3px;padding:3px;border:1px solid var(--line);border-radius:var(--r-sm);background:var(--surface-muted)}.mode-switch button{min-height:34px;border:1px solid transparent;border-radius:calc(var(--r-sm) - 2px);padding:5px 18px;background:transparent;color:var(--muted)}.mode-switch button[aria-pressed=\"true\"]{border-color:var(--line-strong);background:var(--surface);color:var(--accent);font-weight:600}.memory-note{font-size:.85em}\n.stages{display:flex;gap:4px;margin-bottom:var(--gap);padding:8px;border:1px solid var(--line);border-radius:var(--r-lg);background:var(--surface);overflow-x:auto}.stages button{flex:1;display:flex;align-items:center;justify-content:center;gap:8px;white-space:nowrap;padding:8px;border:0;border-radius:var(--r-sm);background:transparent;color:var(--muted);font-size:.9em}.stages button span{font-family:ui-monospace,monospace;color:var(--ink-soft);font-size:.85em}.stages button[aria-current=\"step\"]{color:var(--accent);background:var(--accent-soft);font-weight:600}.stages button[aria-current=\"step\"] span{color:inherit}\n.workbench{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:var(--gap);align-items:start}.conversation-column,.draft-column{display:grid;gap:var(--gap);min-width:0}.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r-lg);min-width:0}.card:not(details){padding:16px}.card summary{cursor:pointer;padding:13px 16px;font-weight:600}.card summary small{float:right;margin-left:10px;font-weight:400;color:var(--muted)}.card-body{padding:0 16px 16px}.section-heading{margin-bottom:10px}.section-heading p{font-size:.87em}.source-panel textarea{font-size:.92em}.source-panel .card-body>small{display:block;margin-top:6px}.dialogue{overflow:hidden}.messages{height:340px;overflow-y:auto;overscroll-behavior:contain;scrollbar-gutter:stable;padding:4px 4px 12px}.empty-message{padding:20px 6px;color:var(--muted)}.empty-message strong{display:block;margin-bottom:8px;color:var(--ink);font-weight:500}.chat-message{padding:12px 0;border-bottom:1px solid var(--line)}.chat-message:last-child{border:0}.chat-message .speaker{display:block;margin-bottom:4px;color:var(--accent);font-size:.82em;font-weight:600}.chat-message.user .speaker{color:var(--muted)}.chat-message p{white-space:pre-wrap;overflow-wrap:anywhere}.suggestions{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0 12px}.suggestions button{max-width:100%;text-align:left;white-space:normal;overflow-wrap:anywhere}.composer-foot{margin-top:10px;gap:8px}.composer-foot>small{flex:1;min-width:150px;font-size:.78em}.manuscript textarea{min-height:350px}.draft-foot{margin-top:10px;gap:8px}.footnote{margin-top:10px;font-size:.82em}.lorebook-panel p{font-size:.87em;margin-bottom:8px}.lorebook-panel button{margin-top:8px}\n.notice{margin:12px 0;padding:10px 14px;border:1px solid var(--line-strong);border-radius:var(--r-sm);background:var(--accent-soft);font-size:.92em;overflow-wrap:anywhere}.notice.error{border-color:var(--danger);background:var(--surface);color:var(--danger)}\ndialog{width:min(540px,calc(100% - 32px));max-height:calc(100% - 32px);padding:var(--pad);border:1px solid var(--line-strong);border-radius:var(--r-lg);background:var(--surface);color:var(--ink);box-shadow:0 16px 60px #0003}dialog::backdrop{background:#15251e66}.dialog-heading{margin-bottom:12px}.dialog-heading h2{font-size:1.1em}.close-button{width:32px;height:32px;border:0;background:var(--surface-muted);border-radius:var(--r-sm);font-size:22px;line-height:1}.field{display:grid;gap:7px;margin-top:16px}.dialog-foot{justify-content:flex-end;margin-top:20px}.draft-list{display:grid;gap:8px;margin:14px 0}.saved-item{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px;border:1px solid var(--line);border-radius:var(--r-sm)}.saved-item div{min-width:0}.saved-item strong{display:block;overflow-wrap:anywhere;font-size:.95em}.saved-item small{display:block;color:var(--muted)}.saved-item button{flex-shrink:0}.compare-dialog{width:min(1120px,calc(100% - 32px))}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:var(--gap)}.comparison section{min-width:0}.comparison pre{min-height:200px;max-height:65vh;overflow:auto;padding:12px;border:1px solid var(--line);border-radius:var(--r-sm);background:var(--surface-muted);white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;font-size:.92em}\n@media(max-width:850px){.workbench{grid-template-columns:1fr}.workbench-head{align-items:flex-start}.workbench-head>.actions{margin-left:auto}.messages{height:320px}.manuscript textarea{min-height:280px}.stages button{flex:0 0 auto}.stages{justify-content:space-between}.comparison{grid-template-columns:1fr}}\n@media(max-width:480px){.designer{padding:12px}.workbench-head>.actions{margin-left:0;width:100%}.workbench-head>.actions button{flex:1;padding-inline:8px}.mode-row{margin-top:16px;gap:8px}.memory-note{font-size:.8em}.card:not(details){padding:12px}.card summary{padding:12px}.card-body{padding:0 12px 12px}.composer-foot>.actions{width:100%;justify-content:flex-end}.draft-foot>.actions{width:100%}.draft-foot>.actions button{flex:1}.stages{gap:2px;padding:5px}.stages button{padding:7px;font-size:.82em;gap:5px}}\n\n/* 嵌入「人格处理」时由外层模式卡导航，隐藏重复的标题与模式开关 */\n.is-embedded .workbench-head .heading{display:none}\n.is-embedded .workbench-head{justify-content:flex-end}\n.is-embedded .mode-row{justify-content:flex-end}\n.is-embedded .mode-row .mode-switch{display:none}\n\n/* 操作区按场景分组：顶部只放工作区设置，正文底部放交付动作 */\n.workbench-head>.actions{gap:6px;flex-wrap:wrap;justify-content:flex-end}\n.section-heading>div{display:grid;gap:2px;min-width:0}\n.draft-hint{color:var(--muted);font-size:.78em;line-height:1.45}\n.manuscript .section-heading{align-items:flex-start}\n.draft-foot{position:sticky;bottom:-1px;z-index:2;margin-top:10px;padding-top:10px;border-top:1px solid var(--line);background:var(--surface)}\n.draft-foot .actions{gap:6px;flex-wrap:wrap;justify-content:flex-end}\n.draft-foot .actions .button.primary{min-width:96px}\n@media(max-width:560px){.draft-foot{align-items:flex-start;flex-direction:column}.draft-foot .actions{width:100%}.draft-foot .actions .button{flex:1}}\n\n/* 陪伴小屋语义令牌层\n   单一变量源：主题、密度、圆角、字号、动效全部在此声明。\n\n   色板取向：界面色取自体素小屋本身的材料——木作、草地、黄昏、夜色——\n   而不是从通用仪表盘继承的冷紫。这样界面看起来像屋子的一部分，\n   而不是叠在屋子上面的一块玻璃。\n\n   每套主题必须声明全部 --t-* 变量。令牌被组件直接引用，\n   漏掉一个不会回落成默认值，而是变成无效值（继承失败即透明/黑）。\n   完整性由 tools/audit_theme_tokens.py 校验。 */\n\n/* === 主题色板 ===\n   六套，按明暗分组，每套对应小屋的一个时段或一种陈设风格。\n   :root 不带 data-theme 时用庭院兜底，避免令牌为空。\n\n   每个色板写两条选择器：一条 :root[data-theme=...]（整站生效），\n   一条 [data-theme=...]（同块作用域）。后者是给主题色卡用的——\n   色卡预览元素带上 data-theme 就能取到那套主题的真实色值，\n   于是「色卡里画出来的」就是「选中后真实的」，不需要另抄一份色值。\n   两条选择器必须成对出现，audit_theme_tokens.py 会核对两边的令牌集合一致。 */\n:root,\n:root[data-theme=\"dawn\"],\n[data-theme=\"dawn\"],\n:root[data-theme=\"light\"]{\n  /* 晨雾 · 清晨的浅暖米白，木色点缀 */\n  --t-canvas:#f4f1ea;\n  --t-surface:#fffdf8;\n  --t-surface-soft:#f9f6ef;\n  --t-surface-raised:#ffffff;\n  --t-surface-sunken:#ece7dc;\n  --t-veil:rgba(255,253,248,.72);\n  --t-text:#3b3730;\n  --t-text-strong:#282520;\n  --t-text-soft:#6d675b;\n  /* 弱化文字要能读：原 #8c857a 对画布只有 3.24:1，正文级字号不达 4.5:1。 */\n  --t-text-faint:#726d65;\n  --t-text-invert:#fffdf8;\n  --t-accent:#9a6f45;\n  --t-accent-hover:#7d5936;\n  --t-accent-quiet:#f2e8d9;\n  --t-accent-ink:#7a5636;\n  --t-accent-solid:#8a6540;\n  --t-accent-solid-hover:#725235;\n  --t-on-solid:#fffdf8;\n  --t-line:rgba(120,105,85,.16);\n  --t-line-firm:rgba(120,105,85,.28);\n  --t-ok:#5f7f52;\n  --t-ok-quiet:#eaf0e3;\n  --t-ok-ink:#4e6a43;\n  --t-warn:#a8802f;\n  --t-warn-quiet:#f8efda;\n  --t-warn-ink:#87661f;\n  --t-risk:#a86055;\n  --t-risk-quiet:#f7e9e5;\n  --t-risk-ink:#8a4c43;\n  /* 焦点环必须是实色。带 alpha 的环合成到背景后只有 1.3–2.2:1，\n     WCAG 1.4.11 要求指示器 ≥3:1；六套主题一律改成不透明强调色。 */\n  --t-focus:#896540;\n  --t-shadow:0 8px 28px rgba(96,80,60,.07);\n  --t-shadow-lift:0 14px 36px rgba(96,80,60,.13);\n  --t-brand:#a87d52;\n  /* 场景联动：界面用晨光时，小屋也走清晨光照 */\n  --t-scene-light:dawn;\n  --skin-heading-font:\"Noto Serif SC\",\"Songti SC\",\"SimSun\",serif;\n  --skin-canvas-pattern:linear-gradient(90deg,color-mix(in srgb,var(--t-accent) 8%,transparent) 1px,transparent 1px),\n    repeating-linear-gradient(0deg,transparent 0 31px,color-mix(in srgb,var(--t-accent) 5%,transparent) 31px 32px);\n  --skin-canvas-size:40px 100%,auto;\n  --skin-r-2xs:2px;--skin-r-xs:5px;--skin-r-sm:8px;--skin-r-md:11px;--skin-r-lg:15px;--skin-r-xl:20px;\n}\n\n\n:root[data-theme=\"courtyard\"],\n[data-theme=\"courtyard\"]{\n  /* 庭院 · 日间的清爽草绿与天光，是默认主题 */\n  --t-canvas:#eef3ec;\n  --t-surface:#fdfefb;\n  --t-surface-soft:#f5f9f3;\n  --t-surface-raised:#ffffff;\n  --t-surface-sunken:#e3ebe0;\n  --t-veil:rgba(253,254,251,.72);\n  --t-text:#333a33;\n  --t-text-strong:#212822;\n  --t-text-soft:#616b60;\n  --t-text-faint:#687068;\n  --t-text-invert:#fdfefb;\n  --t-accent:#4a7c50;\n  --t-accent-hover:#3a6540;\n  --t-accent-quiet:#e6efe4;\n  --t-accent-ink:#3b6541;\n  --t-accent-solid:#46754c;\n  --t-accent-solid-hover:#375e3d;\n  --t-on-solid:#fdfefb;\n  --t-line:rgba(74,90,74,.14);\n  --t-line-firm:rgba(74,90,74,.26);\n  --t-ok:#4a7c50;\n  --t-ok-quiet:#e4efe2;\n  --t-ok-ink:#3b6541;\n  --t-warn:#9c7422;\n  --t-warn-quiet:#f7f0dc;\n  --t-warn-ink:#7d5c17;\n  --t-risk:#a5524a;\n  --t-risk-quiet:#f7e9e6;\n  --t-risk-ink:#874139;\n  --t-focus:#46754c;\n  --t-shadow:0 8px 28px rgba(58,80,60,.06);\n  --t-shadow-lift:0 14px 36px rgba(58,80,60,.12);\n  --t-brand:#57875d;\n  --t-scene-light:day;\n  --skin-heading-font:\"MiSans\",\"Microsoft YaHei\",\"PingFang SC\",system-ui,sans-serif;\n  --skin-canvas-pattern:linear-gradient(90deg,transparent 0 63px,color-mix(in srgb,var(--t-accent) 5%,transparent) 63px 64px);\n  --skin-canvas-size:auto;\n  --skin-r-2xs:3px;--skin-r-xs:7px;--skin-r-sm:10px;--skin-r-md:14px;--skin-r-lg:19px;--skin-r-xl:26px;\n}\n\n\n:root[data-theme=\"dusk\"],\n[data-theme=\"dusk\"]{\n  /* 暮色 · 偏深暖的琥珀与陶土，傍晚 */\n  --t-canvas:#faf1e8;\n  --t-surface:#fffaf4;\n  --t-surface-soft:#fbf4ec;\n  --t-surface-raised:#ffffff;\n  --t-surface-sunken:#efe0d3;\n  --t-veil:rgba(255,250,244,.74);\n  --t-text:#453831;\n  --t-text-strong:#312721;\n  --t-text-soft:#7a685e;\n  --t-text-faint:#796b64;\n  --t-text-invert:#fffaf4;\n  --t-accent:#b85f42;\n  --t-accent-hover:#9b4b32;\n  --t-accent-quiet:#fae5da;\n  --t-accent-ink:#964b33;\n  --t-accent-solid:#a8553b;\n  --t-accent-solid-hover:#8d452f;\n  --t-on-solid:#fffaf4;\n  --t-line:rgba(120,88,70,.16);\n  --t-line-firm:rgba(120,88,70,.28);\n  --t-ok:#5b7f5c;\n  --t-ok-quiet:#e9f0e5;\n  --t-ok-ink:#4a6a4b;\n  --t-warn:#a8792b;\n  --t-warn-quiet:#f9eed8;\n  --t-warn-ink:#89601d;\n  --t-risk:#ab4f45;\n  --t-risk-quiet:#fae7e4;\n  --t-risk-ink:#8d3f36;\n  --t-focus:#a7553b;\n  --t-shadow:0 8px 28px rgba(110,74,54,.08);\n  --t-shadow-lift:0 14px 36px rgba(110,74,54,.14);\n  --t-brand:#c26c4d;\n  --t-scene-light:dusk;\n  --skin-heading-font:\"Noto Serif SC\",\"Songti SC\",\"SimSun\",serif;\n  --skin-canvas-pattern:repeating-linear-gradient(135deg,transparent 0 11px,color-mix(in srgb,var(--t-accent) 4%,transparent) 11px 12px);\n  --skin-canvas-size:auto;\n  --skin-r-2xs:2px;--skin-r-xs:4px;--skin-r-sm:7px;--skin-r-md:10px;--skin-r-lg:14px;--skin-r-xl:18px;\n}\n\n\n:root[data-theme=\"night\"],\n[data-theme=\"night\"],\n:root[data-theme=\"dark\"],\n[data-theme=\"dark\"]{\n  /* 夜读 · 低照度靛蓝与月白，夜间查看 */\n  --t-canvas:#15171f;\n  --t-surface:#22252f;\n  --t-surface-soft:#1c1f28;\n  --t-surface-raised:#282c38;\n  --t-surface-sunken:#181a22;\n  --t-veil:rgba(28,30,39,.82);\n  --t-text:#e5e6ec;\n  --t-text-strong:#f5f5f9;\n  --t-text-soft:#a5a8b8;\n  --t-text-faint:#878b9a;\n  --t-text-invert:#171920;\n  --t-accent:#93a8d8;\n  --t-accent-hover:#7b92c8;\n  --t-accent-quiet:#252a3a;\n  --t-accent-ink:#b3c3e8;\n  --t-accent-solid:#61749f;\n  --t-accent-solid-hover:#7b92c8;\n  --t-on-solid:#ffffff;\n  --t-line:rgba(255,255,255,.10);\n  --t-line-firm:rgba(255,255,255,.20);\n  --t-ok:#6fbf9a;\n  --t-ok-quiet:#1c3029;\n  --t-ok-ink:#87d0ad;\n  --t-warn:#d9ae6d;\n  --t-warn-quiet:#312818;\n  --t-warn-ink:#e6c287;\n  --t-risk:#d18f98;\n  --t-risk-quiet:#301f23;\n  --t-risk-ink:#dda1aa;\n  --t-focus:#93a8d8;\n  --t-shadow:0 10px 26px rgba(0,0,0,.32);\n  --t-shadow-lift:0 14px 32px rgba(0,0,0,.46);\n  --t-brand:#8b9ed0;\n  --t-scene-light:night;\n  --skin-heading-font:\"Noto Serif SC\",\"Songti SC\",\"SimSun\",serif;\n  --skin-canvas-pattern:repeating-linear-gradient(0deg,transparent 0 35px,color-mix(in srgb,var(--t-accent) 5%,transparent) 35px 36px);\n  --skin-canvas-size:auto;\n  --skin-r-2xs:2px;--skin-r-xs:4px;--skin-r-sm:7px;--skin-r-md:10px;--skin-r-lg:14px;--skin-r-xl:18px;\n}\n\n\n:root[data-theme=\"walnut\"],\n[data-theme=\"walnut\"]{\n  /* 深林 · 胡桃木与苔绿的深色，暖而稳 */\n  --t-canvas:#1d1a16;\n  --t-surface:#2a2620;\n  --t-surface-soft:#242019;\n  --t-surface-raised:#332e26;\n  --t-surface-sunken:#1a1713;\n  --t-veil:rgba(36,32,25,.84);\n  --t-text:#e8e2d6;\n  --t-text-strong:#f5f0e6;\n  --t-text-soft:#b3aa99;\n  --t-text-faint:#948c7d;\n  --t-text-invert:#1a1713;\n  --t-accent:#b5926a;\n  --t-accent-hover:#c8a67f;\n  --t-accent-quiet:#332c22;\n  --t-accent-ink:#d0b28e;\n  --t-accent-solid:#8a6c4a;\n  --t-accent-solid-hover:#a3805a;\n  --t-on-solid:#ffffff;\n  --t-line:rgba(232,226,214,.12);\n  --t-line-firm:rgba(232,226,214,.22);\n  --t-ok:#8aa87a;\n  --t-ok-quiet:#262b1f;\n  --t-ok-ink:#a3bf92;\n  --t-warn:#cfa75f;\n  --t-warn-quiet:#2e2718;\n  --t-warn-ink:#ddba7b;\n  --t-risk:#c98a80;\n  --t-risk-quiet:#2f2220;\n  --t-risk-ink:#d79f96;\n  --t-focus:#b5926a;\n  --t-shadow:0 10px 26px rgba(0,0,0,.34);\n  --t-shadow-lift:0 14px 32px rgba(0,0,0,.48);\n  --t-brand:#aa8a63;\n  --t-scene-light:dusk;\n  --skin-heading-font:\"FangSong\",\"STSong\",\"Songti SC\",serif;\n  --skin-canvas-pattern:repeating-linear-gradient(90deg,transparent 0 79px,color-mix(in srgb,var(--t-accent) 5%,transparent) 79px 80px);\n  --skin-canvas-size:auto;\n  --skin-r-2xs:1px;--skin-r-xs:3px;--skin-r-sm:5px;--skin-r-md:8px;--skin-r-lg:12px;--skin-r-xl:16px;\n}\n\n\n:root[data-theme=\"contrast\"],\n[data-theme=\"contrast\"]{\n  /* 高对比 · 纯黑白加单一高饱和强调，给弱视与强光环境 */\n  --t-canvas:#ffffff;\n  --t-surface:#ffffff;\n  --t-surface-soft:#f4f4f4;\n  --t-surface-raised:#ffffff;\n  --t-surface-sunken:#e8e8e8;\n  --t-veil:rgba(255,255,255,.92);\n  --t-text:#000000;\n  --t-text-strong:#000000;\n  --t-text-soft:#2b2b2b;\n  --t-text-faint:#444444;\n  --t-text-invert:#ffffff;\n  --t-accent:#0033cc;\n  --t-accent-hover:#002599;\n  --t-accent-quiet:#e0e8ff;\n  --t-accent-ink:#002599;\n  --t-accent-solid:#0033cc;\n  --t-accent-solid-hover:#002599;\n  --t-on-solid:#ffffff;\n  --t-line:rgba(0,0,0,.42);\n  --t-line-firm:rgba(0,0,0,.72);\n  --t-ok:#0a6b2f;\n  --t-ok-quiet:#dff5e5;\n  --t-ok-ink:#075423;\n  --t-warn:#8a5a00;\n  --t-warn-quiet:#fdf0d5;\n  --t-warn-ink:#6b4500;\n  --t-risk:#a80016;\n  --t-risk-quiet:#fde5e8;\n  --t-risk-ink:#840012;\n  --t-focus:#0033cc;\n  --t-shadow:0 2px 0 rgba(0,0,0,.28);\n  --t-shadow-lift:0 3px 0 rgba(0,0,0,.42);\n  --t-brand:#0033cc;\n  --t-scene-light:day;\n  --skin-heading-font:\"MiSans\",\"Microsoft YaHei\",\"PingFang SC\",system-ui,sans-serif;\n  --skin-canvas-pattern:none;\n  --skin-canvas-size:auto;\n  --skin-r-2xs:0px;--skin-r-xs:1px;--skin-r-sm:2px;--skin-r-md:3px;--skin-r-lg:4px;--skin-r-xl:6px;\n}\n/* Bundled workspaces project the cottage palette into their existing variables.\n   tools/sync_framework_page.py supplies --t-* from tokens.css without copying\n   layout, dimensions or component rules into the workspace. */\n:root[data-theme] {\n  color-scheme: light;\n  --radius:var(--skin-r-md,12px);\n  --page: var(--t-canvas);\n  --surface: var(--t-surface);\n  --surface-muted: var(--t-surface-soft);\n  --ink: var(--t-text);\n  --muted: var(--t-text-soft);\n  --ink-soft: var(--t-text-faint);\n  --line: var(--t-line);\n  --line-strong: var(--t-line-firm);\n  --accent: var(--t-accent);\n  --accent-strong: var(--t-accent-hover);\n  --accent-soft: var(--t-accent-quiet);\n  --green: var(--t-ok-ink);\n  --green-soft: var(--t-ok-quiet);\n  --success: var(--t-ok-ink);\n  --success-soft: var(--t-ok-quiet);\n  --amber: var(--t-warn-ink);\n  --amber-soft: var(--t-warn-quiet);\n  --warning: var(--t-warn-ink);\n  --warning-soft: var(--t-warn-quiet);\n  --danger: var(--t-risk-ink);\n  --danger-soft: var(--t-risk-quiet);\n  --info: var(--t-accent-ink);\n  --info-soft: var(--t-accent-quiet);\n  --shadow: var(--t-shadow);\n  --shadow-lift: var(--t-shadow-lift);\n  --backdrop: color-mix(in srgb, var(--t-text-strong) 45%, transparent);\n}\n:root[data-theme=\"night\"], :root[data-theme=\"walnut\"] { color-scheme: dark; }\n:root[data-theme] body {\n  background-image:var(--skin-canvas-pattern,none);\n  background-size:var(--skin-canvas-size,auto);\n}\n:root[data-theme] h1,:root[data-theme] h2 {\n  font-family:var(--skin-heading-font,inherit);\n}\n.extension-status-hero{position:relative;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:var(--sp-3);padding:var(--sp-4);border:1px solid var(--line);border-radius:var(--r-md);background:linear-gradient(135deg,var(--surface),color-mix(in srgb,var(--accent-soft) 55%,var(--surface)));overflow:hidden;animation:extension-rise .45s cubic-bezier(.22,.8,.2,1) both}\n.extension-status-hero::after{position:absolute;inset:0 auto 0 0;width:34%;background:linear-gradient(90deg,color-mix(in srgb,var(--accent) 10%,transparent),transparent);content:\"\";pointer-events:none}\n.extension-status-icon{position:relative;z-index:1;display:grid;width:48px;height:48px;place-items:center;border-radius:var(--r-md);background:var(--accent-soft);color:var(--accent);font-size:var(--fs-display);box-shadow:0 0 0 7px color-mix(in srgb,var(--accent) 7%,transparent)}\n.extension-status-copy{position:relative;z-index:1;min-width:0}.extension-status-copy h3{margin:0;font-size:var(--fs-head)}.extension-status-copy p{margin:var(--sp-1) 0 0;color:var(--muted);font-size:var(--fs-body);line-height:1.55}.extension-status-chip{position:relative;z-index:1;padding:var(--sp-1) var(--sp-2);border:1px solid var(--line-strong);border-radius:var(--r-pill);color:var(--muted);font-size:var(--fs-tiny);white-space:nowrap}.extension-status-hero.ready .extension-status-chip{border-color:color-mix(in srgb,var(--green) 35%,var(--line));background:var(--green-soft);color:var(--green)}.extension-status-hero.warn .extension-status-chip{border-color:color-mix(in srgb,var(--amber) 35%,var(--line));background:var(--amber-soft);color:var(--amber)}\n.extension-flow{display:flex;align-items:center;gap:var(--sp-2);margin:var(--sp-4) 0 var(--sp-5);padding:0 3px}.extension-flow-step{display:grid;grid-template-columns:auto 1fr;column-gap:var(--sp-2);min-width:86px;color:var(--muted);font-size:var(--fs-tiny)}.extension-flow-step b{grid-row:span 2;display:grid;width:23px;height:23px;place-items:center;border-radius:var(--r-xs);background:var(--surface-muted);color:var(--ink-soft);font-size:var(--fs-micro)}.extension-flow-step span{font-weight:700}.extension-flow-step small{font-size:var(--fs-micro);color:var(--ink-soft)}.extension-flow-step.done b{background:var(--accent-soft);color:var(--accent)}.extension-flow-line{flex:1;height:1px;background:linear-gradient(90deg,var(--accent),var(--line-strong));animation:extension-line 1s ease both}\n.extension-live-panel{position:relative;margin:0 0 var(--sp-4);padding:var(--sp-4) var(--sp-4);border:1px solid color-mix(in srgb,var(--accent) 26%,var(--line));border-radius:var(--r-sm);background:var(--accent-soft);overflow:hidden}.extension-live-panel::before{position:absolute;top:0;bottom:0;left:0;width:3px;background:var(--accent);content:\"\"}.extension-live-panel h3{margin:0 0 var(--sp-1);font-size:var(--fs-lead)}.extension-live-panel p{margin:0;color:var(--muted);font-size:var(--fs-body);line-height:1.6}\n.extension-actions{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);margin-top:var(--sp-5);padding-top:var(--sp-4);border-top:1px solid var(--line)}.extension-actions strong{font-size:var(--fs-body)}.extension-actions p{margin:var(--sp-1) 0 0;color:var(--muted);font-size:var(--fs-tiny)}.extension-actions .dialog-actions{margin:0}\n@keyframes extension-rise{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}@keyframes extension-line{from{transform:scaleX(0);transform-origin:left}to{transform:scaleX(1)}}\n@media (max-width:620px){.extension-status-hero{grid-template-columns:auto 1fr}.extension-status-chip{grid-column:2;justify-self:start}.extension-flow{gap:var(--sp-1)}.extension-flow-step{min-width:0;flex:1}.extension-flow-line{max-width:18px}.extension-actions{align-items:flex-start;flex-direction:column}.extension-actions .dialog-actions{width:100%;flex-wrap:wrap}}\n@media (prefers-reduced-motion:reduce){.extension-status-hero,.extension-flow-line{animation:none}}\n</style>\n  \n  \n</head>\n<body>\n  <main class=\"designer\">\n    <header class=\"workbench-head\">\n      <div class=\"heading\"><span class=\"mark\" aria-hidden=\"true\">她</span><div><h1>新的她</h1><p class=\"muted\">一起推敲她的性格、来历，以及说话的方式。</p></div></div>\n      <div class=\"actions\"><button id=\"choose-model\" class=\"button small\" type=\"button\">选择模型</button><button id=\"open-drafts\" class=\"button small\" type=\"button\">已存草稿</button><button id=\"retry-save\" class=\"button small\" type=\"button\" hidden>确认上次保存</button><button id=\"save-draft\" class=\"button small\" type=\"button\">保存草稿</button></div>\n    </header>\n    <div id=\"notice\" class=\"notice\" role=\"status\" aria-live=\"polite\" hidden></div>\n    <div class=\"mode-row\">\n      <div class=\"mode-switch\" role=\"group\" aria-label=\"设计模式\" hidden><button type=\"button\" data-mode=\"optimize\" aria-pressed=\"true\">拟人优化</button><button type=\"button\" data-mode=\"create\" aria-pressed=\"false\">创建人格</button></div>\n      <span class=\"memory-note\">未保存的进度仅留在此扩展页，刷新或离开后清空。</span>\n    </div>\n    <nav class=\"stages\" aria-label=\"共创阶段\">\n      <button type=\"button\" data-stage=\"positioning\"><span>01</span>定位与关系</button>\n      <button type=\"button\" data-stage=\"personality\"><span>02</span>性格与反差</button>\n      <button type=\"button\" data-stage=\"voice\"><span>03</span>说话方式</button>\n      <button type=\"button\" data-stage=\"background\"><span>04</span>背景与偏好</button>\n      <button type=\"button\" data-stage=\"review\"><span>05</span>审核与试演</button>\n    </nav>\n    <div class=\"workbench\">\n      <section class=\"conversation-column\" aria-label=\"讨论人设\">\n        <details id=\"source-panel\" class=\"card source-panel\" open>\n          <summary>作为起点的人设 <small id=\"source-count\">0 字</small></summary>\n          <div class=\"card-body\"><div class=\"section-heading\"><p class=\"muted\">粘贴已有设定，或选一份 AstrBot 人设。</p><button id=\"choose-persona\" class=\"button small\" type=\"button\">选择人设</button></div><label class=\"sr-only\" for=\"source-text\">原人设文本</label><textarea id=\"source-text\" rows=\"7\" maxlength=\"30000\" placeholder=\"把想优化的人设放在这里。先讨论值得调整的地方，再决定怎样改。\"></textarea><small id=\"source-label\" class=\"muted\">可以直接编辑这份起点文本。</small></div>\n        </details>\n        <section class=\"card dialogue\">\n          <div class=\"section-heading\"><h2>一起设计</h2><span id=\"generation-state\" class=\"muted\" role=\"status\"></span></div>\n          <div id=\"messages\" class=\"messages\" role=\"log\" aria-label=\"人设设计对话\" aria-live=\"polite\" aria-relevant=\"additions\"></div>\n          <div id=\"suggestions\" class=\"suggestions\" role=\"group\" aria-label=\"可选回答\"></div>\n          <form id=\"composer\"><label class=\"sr-only\" for=\"chat-input\">你的想法</label><textarea id=\"chat-input\" rows=\"3\" maxlength=\"8000\" placeholder=\"说说想保留或改变的地方，也可以让助手给几个方向。\"></textarea><div class=\"composer-foot\"><small class=\"muted\">可随时改主意，或说“这部分你决定”。Ctrl / ⌘ + Enter 发送</small><div class=\"actions\"><button id=\"retry-turn\" class=\"button small\" type=\"button\" hidden>重试本轮</button><button id=\"stop-turn\" class=\"button small\" type=\"button\" hidden>停止生成</button><button id=\"send-turn\" class=\"button primary\" type=\"submit\" disabled>开始共创</button></div></div></form>\n        </section>\n      </section>\n      <section class=\"draft-column\" aria-label=\"设定与人设稿\">\n        <details class=\"card confirmed-panel\" open><summary>已确认的设定 <small>可编辑</small></summary><div class=\"card-body\"><label class=\"sr-only\" for=\"confirmed\">已确认的设定</label><textarea id=\"confirmed\" rows=\"5\" maxlength=\"16000\" placeholder=\"聊清楚的设定会汇集在这里，你也可以直接修改。\"></textarea></div></details>\n        <section class=\"card manuscript\">\n          <div class=\"section-heading\"><div><h2>人设稿</h2><small class=\"draft-hint\">先聊清楚方向，再整理成稿；也可以直接手写。</small></div><button id=\"generate-draft\" class=\"button small\" type=\"button\">整理成稿</button></div>\n          <label class=\"sr-only\" for=\"draft-text\">可编辑的人设正文</label><textarea id=\"draft-text\" rows=\"17\" maxlength=\"65536\" placeholder=\"确认方向后，点击“整理成稿”。也可以在这里手动写下初稿。\"></textarea>\n          <div class=\"draft-foot\"><small id=\"draft-count\" class=\"muted\">0 字</small><div class=\"actions\"><button id=\"compare\" class=\"button small\" type=\"button\">对照原文</button><button id=\"tryout\" class=\"button small\" type=\"button\">情景试演</button><button id=\"copy-draft\" class=\"button small primary\" type=\"button\">复制正文</button></div></div>\n          <p class=\"footnote\">复制后到 AstrBot 的「人格设置」粘贴；这里保存的是草稿，不会直接改线上人格。</p>\n        </section>\n        <details class=\"card lorebook-panel\"><summary>单独保留的背景 <small>可选</small></summary><div class=\"card-body\"><p class=\"muted\">较长的世界观与故事放在这里，方便另存为世界知识。</p><label class=\"sr-only\" for=\"lorebook\">单独保留的背景条目</label><textarea id=\"lorebook\" rows=\"5\" maxlength=\"20000\"></textarea><button id=\"copy-lorebook\" class=\"button small\" type=\"button\">复制背景</button></div></details>\n      </section>\n    </div>\n    <dialog id=\"model-dialog\" aria-labelledby=\"model-title\"><form id=\"model-form\"><div class=\"dialog-heading\"><h2 id=\"model-title\">选择共创模型</h2><button type=\"button\" data-close class=\"close-button\" aria-label=\"关闭\">×</button></div><p class=\"muted\">使用 AstrBot 已加载的文本模型，仅用于这里的人设设计。</p><label class=\"field\" for=\"model-select\">文本模型<select id=\"model-select\" required></select></label><p id=\"model-empty\" class=\"muted\" hidden>还没有可用的文本模型，请先在 AstrBot 中配置并启用。</p><div class=\"dialog-foot\"><button id=\"refresh-options\" type=\"button\" class=\"button\">重新读取</button><button id=\"confirm-model\" type=\"submit\" class=\"button primary\">使用此模型</button></div></form></dialog>\n    <dialog id=\"persona-dialog\" aria-labelledby=\"persona-title\"><form id=\"persona-form\"><div class=\"dialog-heading\"><h2 id=\"persona-title\">选择人设</h2><button type=\"button\" data-close class=\"close-button\" aria-label=\"关闭\">×</button></div><p class=\"muted\">默认选中 AstrBot 配置使用的人设，载入后可在页面中修改。</p><label class=\"field\" for=\"persona-select\">AstrBot 人设<select id=\"persona-select\" required></select></label><p id=\"persona-empty\" class=\"muted\" hidden>暂时没有读到人设，你仍可粘贴文本或从零设计。</p><p class=\"footnote\">切换为另一人设会开启新的设计，请先保存当前草稿。重新载入同一人设会保留讨论与成稿。</p><div class=\"dialog-foot\"><button id=\"refresh-personas\" type=\"button\" class=\"button\">重新读取</button><button id=\"load-persona\" type=\"submit\" class=\"button primary\">载入人设</button></div></form></dialog>\n    <dialog id=\"switch-persona-dialog\" aria-labelledby=\"switch-persona-title\"><div class=\"dialog-heading\"><h2 id=\"switch-persona-title\">为另一人设开始设计？</h2></div><p class=\"muted\">当前讨论、已确认设定和成稿将被清空。如果还想保留，请先取消并点击“保存草稿”。已保存的版本仍可读取，AstrBot 中的人格不会改变。</p><div class=\"dialog-foot\"><button type=\"button\" data-close class=\"button\">取消，继续编辑</button><button id=\"confirm-persona-switch\" type=\"button\" class=\"button primary\">切换并开始新设计</button></div></dialog>\n    <dialog id=\"save-dialog\" aria-labelledby=\"save-title\"><form id=\"save-form\"><div class=\"dialog-heading\"><h2 id=\"save-title\">保存当前模式的草稿</h2><button type=\"button\" data-close class=\"close-button\" aria-label=\"关闭\">×</button></div><p class=\"muted\">保存对话、设定、人设稿、输入内容及本次模型选择，供以后继续。</p><label class=\"field\" for=\"draft-title\">版本名称<input id=\"draft-title\" type=\"text\" maxlength=\"120\" required></label><div class=\"dialog-foot\"><button type=\"button\" data-close class=\"button\">取消</button><button id=\"confirm-save\" type=\"submit\" class=\"button primary\">保存</button></div></form></dialog>\n    <dialog id=\"drafts-dialog\" aria-labelledby=\"drafts-title\"><div class=\"dialog-heading\"><h2 id=\"drafts-title\">已存草稿</h2><button type=\"button\" data-close class=\"close-button\" aria-label=\"关闭\">×</button></div><p class=\"muted\">读取会替换对应模式当前的编辑内容。</p><div id=\"draft-list\" class=\"draft-list\"></div><button id=\"more-drafts\" class=\"button\" type=\"button\" hidden>更早的版本</button><div class=\"dialog-foot\"><button id=\"new-design\" type=\"button\" class=\"button\">新建一份</button></div></dialog>\n    <dialog id=\"reset-dialog\" aria-labelledby=\"reset-title\"><div class=\"dialog-heading\"><h2 id=\"reset-title\">重新开始当前模式</h2><button type=\"button\" data-close class=\"close-button\" aria-label=\"关闭\">×</button></div><p class=\"muted\">将清空当前模式的对话和编辑内容。如果还想继续使用这份设定，请先保存草稿。</p><div class=\"dialog-foot\"><button type=\"button\" data-close class=\"button\">继续编辑</button><button id=\"confirm-reset\" type=\"button\" class=\"button primary\">重新开始</button></div></dialog>\n    <dialog id=\"compare-dialog\" class=\"compare-dialog\" aria-labelledby=\"compare-title\"><div class=\"dialog-heading\"><h2 id=\"compare-title\">原文与当前稿</h2><button type=\"button\" data-close class=\"close-button\" aria-label=\"关闭\">×</button></div><div class=\"comparison\"><section><h3>起点文本</h3><pre id=\"compare-source\"></pre></section><section><h3>当前人设稿</h3><pre id=\"compare-draft\"></pre></section></div></dialog>\n    <noscript>请启用 JavaScript 后使用人设设计。</noscript>\n  </main>\n<script>/* Opaque-origin compatible bridge for bundled workspaces. */\n\"use strict\";\n(() => {\n  const pending=new Map();let count=0,context=null,readyResolve;\n  const DEFAULT_REQUEST_TIMEOUT_MS=18000,MAX_REQUEST_TIMEOUT_MS=300000;\n  const ready=new Promise(resolve=>{readyResolve=resolve;});\n  const send=payload=>parent.postMessage({channel:\"companion-workspace\",...payload},\"*\");\n  /* 外观维度：主题沿用原有通道，另外四项按 name/value 应用。\n     工作区各自的样式表只用得上其中一部分，未声明的维度不会产生副作用。\n     主题列表取自 theme.js 注册表，不在这里再抄一份——抄一份就会飘，\n     主页面加主题而工作区不认，值会被这个白名单挡掉、主题静默不生效。 */\n  const themeIds = globalThis.CompanionTheme?.IDS || [\"courtyard\",\"dawn\",\"dusk\",\"night\",\"walnut\",\"contrast\"];\n  const appearanceDimensions={\n    theme:{dataset:\"theme\",values:themeIds},\n    density:{dataset:\"density\",values:[\"compact\",\"standard\",\"roomy\"]},\n    radius:{dataset:\"radius\",values:[\"sharp\",\"standard\",\"round\"]},\n    typeScale:{dataset:\"typeScale\",values:[\"s\",\"m\",\"l\",\"xl\"]},\n    motion:{dataset:\"motion\",values:[\"full\",\"low\",\"off\"]},\n  };\n  const applyDimension=(name,value)=>{\n    const spec=appearanceDimensions[name];\n    // 主题额外走一次旧名迁移：工作区若被单独打开，localStorage 里可能还是 mist/grove/coral。\n    if(name===\"theme\"&&globalThis.CompanionTheme)value=globalThis.CompanionTheme.migrate(value);\n    if(!spec||!spec.values.includes(value))return false;\n    document.documentElement.dataset[spec.dataset]=value;\n    document.dispatchEvent(new CustomEvent(\"companion-appearance-change\",{detail:{name,value}}));\n    return true;\n  };\n  window.addEventListener(\"message\",event=>{\n    if(event.source!==parent||event.data?.channel!==\"companion-workspace\")return;\n    const message=event.data;\n    if(message.kind===\"context\"){context=message.context;readyResolve(context);return;}\n    if(message.kind===\"host-mappings-refreshed\"){\n      document.dispatchEvent(new CustomEvent(\"companion-mappings-change\",{detail:message}));return;\n    }\n    if(message.kind===\"host-mappings-refresh-failed\"){\n      document.dispatchEvent(new CustomEvent(\"companion-mappings-refresh-failed\",{detail:message}));return;\n    }\n    if(message.kind===\"theme\"&&appearanceDimensions.theme.values.includes(message.theme)){\n      applyDimension(\"theme\",message.theme);\n      document.dispatchEvent(new CustomEvent(\"companion-theme-change\",{detail:{theme:message.theme}}));\n      return;\n    }\n    if(message.kind===\"appearance\"){\n      if(message.appearance)for(const [name,value] of Object.entries(message.appearance))applyDimension(name,value);\n      else applyDimension(message.name,message.value);\n      return;\n    }\n    if(message.kind===\"navigate-failed\"){\n      document.dispatchEvent(new CustomEvent(\"companion-navigate-failed\",{detail:message}));return;\n    }\n    if(message.kind!==\"response\"||!pending.has(message.requestId))return;\n    const item=pending.get(message.requestId);pending.delete(message.requestId);clearTimeout(item.timer);\n    if(message.ok)item.resolve(message.data);else item.reject(Object.assign(new Error(message.error),\n      {code:message.code,reason:message.reason,sourceLabel:message.sourceLabel,\n        confirmed:message.confirmed===true}));\n  });\n  function request(method,path,body,options){return new Promise((resolve,reject)=>{\n    const requestId=\"workspace-\"+(++count);\n    const requested=options?.timeoutMs;\n    const timeoutMs=Number.isInteger(requested)&&requested>=1000\n      ?Math.min(requested,MAX_REQUEST_TIMEOUT_MS):DEFAULT_REQUEST_TIMEOUT_MS;\n    const timer=setTimeout(()=>{pending.delete(requestId);reject(Object.assign(\n      new Error(\"未收到执行结果，请核对后重试本次操作。\"),{code:\"bridge_timeout\",confirmed:false}));},timeoutMs+1000);\n    pending.set(requestId,{resolve,reject,timer});send({kind:\"request\",requestId,method,path,body,timeoutMs});\n  });}\n  window.AstrBotPluginPage={ready:()=>ready,getContext:()=>context,\n    apiGet:(path,body,options)=>request(\"GET\",path,body,options),\n    apiPost:(path,body,options)=>request(\"POST\",path,body,options)};\n  document.addEventListener(\"DOMContentLoaded\",async()=>{\n    document.querySelectorAll(\"#start-host,#stop-host\").forEach(el=>el.hidden=true);\n    await ready;\n    if(context.tab)document.querySelector('[data-tab=\"'+CSS.escape(context.tab)+'\"]')?.click();\n    let last=0;\n    new ResizeObserver(()=>{const height=document.body.scrollHeight;if(height!==last){last=height;send({kind:\"resize\",height});}}).observe(document.body);\n  });\n  send({kind:\"ready\"});\n})();\n\n\"use strict\";\n(() => {\n  if (window.parent !== window) document.documentElement.classList.add(\"is-embedded\");\n  const $ = id => document.getElementById(id);\n  const STAGES = [\"positioning\", \"personality\", \"voice\", \"background\", \"review\"];\n  const LABELS = {optimize: \"拟人优化\", create: \"创建人格\"};\n  const errors = {\n    dashboard_identity_required: \"请从已登录的 AstrBot 管理界面打开此页。\",\n    core_access_required: \"当前账号没有管理本安装的权限。\",\n    persona_designer_invalid: \"设计内容过长或格式不完整，请检查后重试。\",\n    persona_designer_unavailable: \"新的她暂时不可用，当前编辑内容仍保留，可以稍后重试。\",\n    persona_designer_model_rejected: \"模型没有接受这次设计请求；可以换一个文本模型，或缩短人设/对话后重试。\",\n    persona_designer_model_missing: \"所选文本模型尚未加载，请重新选择模型。\",\n    persona_designer_source_required: \"先输入人设，或从“选择人设”载入一份。\",\n    persona_designer_draft_required: \"先生成或填写一份人设稿，再进行情景试演。\",\n    persona_designer_response_invalid: \"模型返回的设计结果不完整，请重试本轮或换一个文本模型。\",\n    persona_designer_context_full: \"这次设计的内容较长，请先保存草稿，再精简对话后继续。\",\n    persona_designer_busy: \"还有一轮设计正在生成，请等待完成或先停止生成。\",\n    persona_designer_timeout: \"本轮生成超时，输入与设计内容仍保留，可以重试。\",\n    persona_designer_cancelled: \"本轮生成已停止，输入与设计内容仍保留。\",\n    persona_designer_stopped: \"功能已停止，请重新打开插件页面。\",\n    persona_designer_model_changed: \"模型已经重新加载，请重新发起本轮设计。\",\n    persona_designer_persona_missing: \"这份人设已不在 AstrBot 列表中，请重新选择。\",\n    persona_designer_source_large: \"这份人设较长，请手动选取需要优化的部分。\",\n    persona_designer_draft_missing: \"这份草稿不存在或不属于当前账号。\",\n    persona_designer_save_conflict: \"草稿内容已变化，请作为新版本保存。\",\n    bridge_timeout: \"未能确认本次操作的结果，当前内容仍保留。保存操作可重试确认。\",\n  };\n  const newDocument = mode => ({mode, stage: \"positioning\", provider_id: \"\", source_persona_id: \"\", source_text: \"\",\n    confirmed: \"\", draft: \"\", lorebook: \"\", input: \"\", messages: [], options: []});\n  const fresh = () => ({version: 1, activeMode: \"optimize\", sessions: {\n    optimize: {document: newDocument(\"optimize\")}, create: {document: newDocument(\"create\")}}, pendingSave: null});\n  const copy = value => JSON.parse(JSON.stringify(value));\n  const uid = () => Array.from(crypto.getRandomValues(new Uint8Array(16)), b => b.toString(16).padStart(2, \"0\")).join(\"\");\n  const node = (tag, text, className) => {\n    const el = document.createElement(tag);\n    if (text !== undefined) el.textContent = text;\n    if (className) el.className = className;\n    return el;\n  };\n  let bridge, root = fresh(), options = {models: [], personas: []}, loaded = false, disposed = false;\n  let working = false, nextBefore = null, pollTimer, loadingDrafts = false, polling = false;\n  let pendingPersonaId = \"\";\n  let entryMode = \"\";\n  const session = () => root.sessions[root.activeMode];\n  const doc = () => session().document;\n  const generating = () => Object.values(root.sessions).some(s => s.pending);\n  const errorText = error => errors[error?.code] || errors[error?.message]\n    || \"这次操作没有完成，当前编辑内容仍保留，请稍后重试。\";\n  function unwrap(response) {\n    const wrapped = [\"ok\", \"error\"].includes(response?.status) ? response\n      : response?.status === undefined && [\"ok\", \"error\"].includes(response?.data?.status) ? response.data : null;\n    if (wrapped?.status === \"error\") throw Object.assign(new Error(wrapped.message), {code: wrapped.message});\n    const result = wrapped ? wrapped.data : response;\n    if (!result || typeof result !== \"object\") throw new Error(\"persona_designer_response_invalid\");\n    return result;\n  }\n  async function api(method, path, body, timeoutMs = 18000) {\n    return unwrap(await bridge[method === \"GET\" ? \"apiGet\" : \"apiPost\"](path, body, {timeoutMs}));\n  }\n  function notice(message = \"\", error = false) {\n    $(\"notice\").textContent = message;\n    $(\"notice\").classList.toggle(\"error\", error);\n    $(\"notice\").hidden = !message;\n  }\n  function persist() {\n    if (disposed || !bridge) return Promise.resolve();\n    return api(\"POST\", \"designer/client-state\", root).catch(() => {\n      notice(\"页面内的进度暂未同步，请先保存草稿，再切换其他页面。\", true);\n    });\n  }\n  function controls() {\n    const d = doc(), ownBusy = !!session().pending, anyBusy = generating();\n    const modelAvailable = options.models.some(m => m.id === d.provider_id);\n    $(\"send-turn\").disabled = !loaded || anyBusy || working || !modelAvailable;\n    $(\"send-turn\").textContent = ownBusy ? \"正在共创…\" : d.input.trim() ? \"发送想法\" : d.messages.length ? \"继续共创\" : \"开始共创\";\n    $(\"stop-turn\").hidden = !ownBusy;\n    $(\"retry-turn\").hidden = !session().retry || anyBusy;\n    $(\"generation-state\").textContent = ownBusy ? \"正在推敲，请稍候…\" : anyBusy ? \"另一模式正在生成\" : \"\";\n    [\"source-text\", \"confirmed\", \"draft-text\", \"lorebook\", \"choose-persona\", \"choose-model\"].forEach(id => $(id).disabled = ownBusy || working);\n    $(\"choose-persona\").disabled ||= anyBusy || !!root.pendingSave;\n    [\"generate-draft\", \"tryout\"].forEach(id => $(id).disabled = !loaded || anyBusy || working || !modelAvailable);\n    $(\"tryout\").disabled ||= !d.draft.trim();\n    $(\"generate-draft\").textContent = d.draft.trim() ? \"重新整理成稿\" : \"整理成稿\";\n    const hasContent = d.messages.length > 0\n      || [\"source_text\", \"confirmed\", \"draft\", \"lorebook\", \"input\"].some(key => String(d[key] || \"\").trim());\n    $(\"save-draft\").disabled = !loaded || !!root.pendingSave || anyBusy || working || !hasContent;\n    $(\"retry-save\").hidden = !root.retrySave;\n    $(\"retry-save\").disabled = !!root.pendingSave || anyBusy || working;\n    $(\"compare\").disabled = root.activeMode !== \"optimize\" || !d.source_text;\n    $(\"copy-draft\").disabled = !d.draft;\n    $(\"copy-lorebook\").disabled = !d.lorebook;\n    $(\"source-count\").textContent = Array.from(d.source_text).length + \" 字\";\n    $(\"draft-count\").textContent = Array.from(d.draft).length + \" 字\";\n    document.querySelectorAll(\"[data-stage]\").forEach(el => el.disabled = ownBusy);\n    document.querySelectorAll(\"#suggestions button\").forEach(el => el.disabled = anyBusy || working || !modelAvailable);\n  }\n  function render() {\n    const d = doc();\n    document.querySelectorAll(\"[data-mode]\").forEach(el => el.setAttribute(\"aria-pressed\", String(el.dataset.mode === root.activeMode)));\n    document.querySelectorAll(\"[data-stage]\").forEach(el => {\n      if (el.dataset.stage === d.stage) el.setAttribute(\"aria-current\", \"step\");\n      else el.removeAttribute(\"aria-current\");\n    });\n    $(\"source-panel\").hidden = d.mode !== \"optimize\";\n    for (const [id, key] of [[\"source-text\", \"source_text\"], [\"chat-input\", \"input\"], [\"confirmed\", \"confirmed\"], [\"draft-text\", \"draft\"], [\"lorebook\", \"lorebook\"]]) {\n      if ($(id).value !== d[key]) $(id).value = d[key];\n    }\n    $(\"source-label\").textContent = d.source_persona_id ? \"起点来自：\" + d.source_persona_id + \" · 可在此编辑\" : \"可以直接编辑这份起点文本。\";\n    const model = options.models.find(m => m.id === d.provider_id);\n    $(\"choose-model\").textContent = model ? \"模型 · \" + model.name : d.provider_id ? \"模型已不可用 · 重新选择\" : \"选择模型\";\n    $(\"choose-model\").title = d.provider_id || \"仅用于此页的人设设计\";\n    const log = $(\"messages\");\n    log.replaceChildren();\n    if (!d.messages.length) {\n      const empty = node(\"div\", undefined, \"empty-message\");\n      empty.append(node(\"strong\", d.mode === \"optimize\" ? \"先看看哪些地方值得调整。\" : \"她可以从一个很小的念头开始。\"),\n        node(\"p\", d.mode === \"optimize\" ? \"提供原人设后，说说你遇到的问题，或直接开始，让助手给出具体建议。\" : \"描述一种性格、一段关系或几句你喜欢的话；还没有方向也没关系。\"));\n      log.append(empty);\n    }\n    for (const message of d.messages) {\n      const article = node(\"article\", undefined, \"chat-message \" + message.role);\n      article.append(node(\"span\", message.role === \"user\" ? \"你\" : \"设计助手\", \"speaker\"), node(\"p\", message.content));\n      log.append(article);\n    }\n    log.scrollTop = log.scrollHeight;\n    const suggestions = $(\"suggestions\");\n    suggestions.replaceChildren();\n    const choices = d.options.length ? d.options : d.mode === \"create\" && !d.messages.length\n      ? [\"我有一个大致的角色想法\", \"还没想好，先帮我找方向\", \"从我熟悉的性格出发\"] : [];\n    for (const choice of choices) {\n      const button = node(\"button\", choice, \"button small\"); button.type = \"button\";\n      button.addEventListener(\"click\", () => sendTurn(\"chat\", choice)); suggestions.append(button);\n    }\n    controls();\n  }\n  function fillSelect(id, items, selected, emptyLabel) {\n    const select = $(id); select.replaceChildren();\n    if (!items.length) select.append(new Option(emptyLabel, \"\"));\n    else {\n      if (!selected || !items.some(item => item.id === selected)) select.append(new Option(\"请选择\", \"\"));\n      items.forEach(item => select.append(new Option(item.name + (item.default ? \" · AstrBot 配置使用\" : \"\"), item.id)));\n    }\n    select.value = selected || \"\";\n    select.disabled = !items.length;\n  }\n  async function loadOptions() {\n    try {\n      options = await api(\"GET\", \"designer/options\", {});\n      if (!Array.isArray(options.models) || !Array.isArray(options.personas)) throw new Error(\"persona_designer_response_invalid\");\n      loaded = true;\n      fillSelect(\"model-select\", options.models, doc().provider_id, \"暂无文本模型\");\n      fillSelect(\"persona-select\", options.personas, doc().source_persona_id || options.default_persona_id || options.personas[0]?.id, \"暂无人设\");\n      $(\"model-empty\").hidden = !!options.models.length;\n      $(\"persona-empty\").hidden = !!options.personas.length;\n      $(\"confirm-model\").disabled = !options.models.length;\n      $(\"load-persona\").disabled = !options.personas.length;\n      if (options.persona_issue) notice(options.persona_issue);\n      render();\n    } catch (error) { notice(errorText(error), true); }\n  }\n  function validReply(value) {\n    return value && typeof value.reply === \"string\" && value.reply.trim() && value.reply.length <= 16000\n      && [\"confirmed\", \"draft\", \"lorebook\"].every(key => typeof value[key] === \"string\")\n      && value.confirmed.length <= 16000 && value.draft.length <= 65536 && value.lorebook.length <= 20000\n      && STAGES.includes(value.stage) && Array.isArray(value.options) && value.options.length <= 3\n      && value.options.every(value => typeof value === \"string\" && value.length <= 300);\n  }\n  async function sendTurn(action, text, retry) {\n    if (generating() || working) return;\n    const current = session(), d = doc();\n    if (!options.models.some(m => m.id === d.provider_id)) { $(\"model-dialog\").showModal(); return; }\n    if (d.mode === \"optimize\" && !d.source_text.trim()) { notice(errors.persona_designer_source_required, true); $(\"source-text\").focus(); return; }\n    if (action === \"tryout\" && !d.draft.trim()) { notice(errors.persona_designer_draft_required, true); return; }\n    const user = text || (action === \"draft\" ? \"请根据已经确认的内容，整理一份可编辑的人设稿。\"\n      : action === \"tryout\" ? \"请按当前人设稿进行日常聊天、工具结果转述、被指出疏漏三组情景试演。\"\n      : d.input.trim() ? d.input : d.mode === \"optimize\" ? \"请先分析这份人设，给出具体的优化建议，和我逐步确认。\" : \"我还没有完整想法，请给几个具体方向，和我逐步设计。\" );\n    const state = {...copy(d), messages: retry ? copy(retry.state.messages)\n      : [...copy(d.messages), {role: \"user\", content: user}], options: []};\n    if (state.messages.length > 98) { notice(\"当前对话较长，请保存草稿后开始新的设计。\", true); return; }\n    const request = {request_id: uid(), action, state};\n    current.pending = {id: request.request_id, action, state,\n      input: action === \"chat\" && state.messages[state.messages.length - 1]?.content === d.input ? d.input : null};\n    delete current.retry; delete current.error;\n    notice(); render();\n    await persist();\n    if (disposed) return;\n    // The parent retains the receipt if this iframe is replaced during the call.\n    api(\"POST\", \"designer/turn\", request, 135000).catch(() => {}).finally(() => { if (!disposed) poll(); });\n    schedulePoll();\n  }\n  function schedulePoll() {\n    clearTimeout(pollTimer);\n    if (!disposed && (generating() || root.pendingSave)) pollTimer = setTimeout(poll, 800);\n  }\n  async function poll() {\n    clearTimeout(pollTimer);\n    if (disposed || polling) return;\n    polling = true;\n    try {\n      for (const [mode, current] of Object.entries(root.sessions)) {\n        const pending = current.pending;\n        if (!pending) continue;\n        const receipt = await api(\"GET\", \"designer/client-result\", {id: \"turn:\" + pending.id});\n        if (disposed || current.pending !== pending || receipt.status === \"pending\") continue;\n        let failure;\n        try {\n          if (receipt.status === \"missing\") throw new Error(\"persona_designer_stopped\");\n          if (receipt.status === \"failed\") throw Object.assign(new Error(receipt.code), {code: receipt.code});\n          const reply = unwrap(receipt.data);\n          if (!validReply(reply)) throw new Error(\"persona_designer_response_invalid\");\n          Object.assign(current.document, {messages: [...pending.state.messages, {role: \"assistant\", content: reply.reply}],\n            options: reply.options, confirmed: reply.confirmed, stage: reply.stage, draft: reply.draft, lorebook: reply.lorebook});\n          if (pending.input !== null && current.document.input === pending.input) current.document.input = \"\";\n        } catch (error) { failure = errorText(error); current.retry = {action: pending.action, state: pending.state}; current.error = failure; }\n        delete current.pending;\n        await persist();\n        await api(\"POST\", \"designer/client-ack\", {id: \"turn:\" + pending.id});\n        if (mode === root.activeMode) { notice(failure || \"\", !!failure); render(); }\n        else { notice(LABELS[mode] + (failure ? \"本轮未完成，可切回重试。\" : \"本轮已完成，可以切回查看。\"), !!failure); controls(); }\n      }\n      const save = root.pendingSave;\n      if (save) {\n        const receipt = await api(\"GET\", \"designer/client-result\", {id: \"save:\" + save.id});\n        if (!disposed && root.pendingSave === save && receipt.status !== \"pending\") {\n          try {\n            if (receipt.status !== \"done\") throw Object.assign(new Error(receipt.code || \"bridge_timeout\"), {code: receipt.code});\n            unwrap(receipt.data);\n            root.pendingSave = null; root.retrySave = null;\n            notice(\"已保存“\" + save.title + \"”，下次可从已存草稿继续。\");\n          } catch (error) { root.pendingSave = null; root.retrySave = save; notice(errorText(error) + \" 可点击“确认上次保存”重试确认。\", true); }\n          await persist(); await api(\"POST\", \"designer/client-ack\", {id: \"save:\" + save.id}); controls();\n        }\n      }\n    } catch (error) { if (!disposed) notice(errorText(error), true); }\n    polling = false; schedulePoll();\n  }\n  async function stopTurn() {\n    const pending = session().pending;\n    if (!pending) return;\n    try { await api(\"POST\", \"designer/cancel\", {request_id: pending.id}); notice(\"已请求停止，正在确认本轮状态。\"); }\n    catch (error) { notice(errorText(error), true); }\n  }\n  function openSave() {\n    $(\"draft-title\").value = LABELS[root.activeMode] + \" · \" + new Date().toLocaleString(\"zh-CN\", {hour12: false});\n    $(\"save-dialog\").showModal();\n  }\n  async function saveSnapshot(snapshot) {\n    if (root.pendingSave) return;\n    root.pendingSave = snapshot; notice(\"正在保存草稿…\"); controls();\n    await persist();\n    if (disposed) return;\n    api(\"POST\", \"designer/drafts\", snapshot).catch(() => {}).finally(() => { if (!disposed) poll(); });\n    schedulePoll();\n  }\n  async function listDrafts(before = 0) {\n    if (loadingDrafts) return;\n    loadingDrafts = true;\n    $(\"more-drafts\").disabled = true;\n    if (!before) $(\"draft-list\").replaceChildren(node(\"p\", \"正在读取…\", \"muted\"));\n    try {\n      const result = await api(\"GET\", \"designer/drafts\", before ? {before} : {});\n      if (!Array.isArray(result.items)) throw new Error(\"persona_designer_response_invalid\");\n      if (!before) $(\"draft-list\").replaceChildren();\n      if (!result.items.length && !before) $(\"draft-list\").append(node(\"p\", \"还没有手动保存过的草稿。\", \"muted\"));\n      for (const item of result.items) {\n        const row = node(\"article\", undefined, \"saved-item\"), description = node(\"div\");\n        description.append(node(\"strong\", item.title), node(\"small\", new Date(item.created_at).toLocaleString(\"zh-CN\", {hour12: false})));\n        const button = node(\"button\", \"读取\", \"button small\"); button.type = \"button\";\n        button.addEventListener(\"click\", async () => {\n          if (generating() || root.pendingSave) { notice(\"请先等待本轮操作完成，再读取草稿。\", true); $(\"drafts-dialog\").close(); return; }\n          working = true; controls(); button.disabled = true;\n          try {\n            const saved = await api(\"GET\", \"designer/draft\", {id: item.id});\n            const d = saved.state;\n            if (![\"optimize\", \"create\"].includes(d?.mode) || !Array.isArray(d.messages)) throw new Error(\"persona_designer_response_invalid\");\n            root.sessions[d.mode] = {document: d}; root.activeMode = d.mode;\n            await persist();\n            if (entryMode && entryMode !== d.mode) {\n              entryMode = d.mode;\n              parent.postMessage({channel: \"companion-workspace\", kind: \"designer-mode\", mode: d.mode}, \"*\");\n            }\n            $(\"drafts-dialog\").close(); notice(\"已读取“\" + saved.title + \"”。\"); render();\n          } catch (error) { notice(errorText(error), true); } finally { working = false; button.disabled = false; controls(); }\n        });\n        row.append(description, button); $(\"draft-list\").append(row);\n      }\n      nextBefore = result.next_before;\n      $(\"more-drafts\").hidden = !nextBefore;\n    } catch (error) { $(\"draft-list\").replaceChildren(node(\"p\", errorText(error), \"muted\")); }\n    finally { loadingDrafts = false; $(\"more-drafts\").disabled = false; }\n  }\n  async function copyText(id) {\n    const input = $(id);\n    const done = id === \"lorebook\" ? \"已复制背景，可以到 AstrBot 的世界知识中粘贴。\"\n      : \"已复制正文，去 AstrBot「人格设置」粘贴即可；这里不会直接改线上人格。\";\n    try { await navigator.clipboard.writeText(input.value); notice(done); }\n    catch {\n      input.focus(); input.select();\n      try { if (!document.execCommand(\"copy\")) throw new Error(); notice(done); }\n      catch { notice(\"已选中文本，请使用系统的复制操作。\"); }\n    }\n  }\n  function selectMode(mode) {\n    const provider = doc().provider_id; root.activeMode = mode;\n    if (!doc().provider_id) doc().provider_id = provider;\n  }\n  document.querySelectorAll(\"[data-mode]\").forEach(button => button.addEventListener(\"click\", () => {\n    selectMode(button.dataset.mode);\n    persist(); notice(session().error || \"\", !!session().error); render();\n  }));\n  document.querySelectorAll(\"[data-stage]\").forEach(button => button.addEventListener(\"click\", () => {\n    doc().stage = button.dataset.stage;\n    if (!doc().input) doc().input = \"我们先聊“\" + button.textContent.replace(/^\\d+/, \"\").trim() + \"”这一部分。\";\n    persist(); render(); $(\"chat-input\").focus();\n  }));\n  for (const [id, key] of [[\"source-text\", \"source_text\"], [\"chat-input\", \"input\"], [\"confirmed\", \"confirmed\"], [\"draft-text\", \"draft\"], [\"lorebook\", \"lorebook\"]]) {\n    $(id).addEventListener(\"input\", () => { doc()[key] = $(id).value; persist(); controls(); });\n  }\n  document.querySelectorAll(\"[data-close]\").forEach(button => button.addEventListener(\"click\", () => button.closest(\"dialog\").close()));\n  $(\"composer\").addEventListener(\"submit\", event => { event.preventDefault(); sendTurn(\"chat\"); });\n  $(\"chat-input\").addEventListener(\"keydown\", event => {\n    if (event.key === \"Enter\" && (event.ctrlKey || event.metaKey) && !event.isComposing) { event.preventDefault(); sendTurn(\"chat\"); }\n  });\n  $(\"generate-draft\").addEventListener(\"click\", () => sendTurn(\"draft\"));\n  $(\"tryout\").addEventListener(\"click\", () => sendTurn(\"tryout\"));\n  $(\"retry-turn\").addEventListener(\"click\", () => { const retry = session().retry; if (retry) sendTurn(retry.action, null, retry); });\n  $(\"stop-turn\").addEventListener(\"click\", stopTurn);\n  $(\"choose-model\").addEventListener(\"click\", () => {\n    fillSelect(\"model-select\", options.models, doc().provider_id, \"暂无文本模型\"); $(\"model-dialog\").showModal();\n  });\n  $(\"model-form\").addEventListener(\"submit\", event => {\n    event.preventDefault(); if (!$(\"model-select\").value) return;\n    doc().provider_id = $(\"model-select\").value; persist(); $(\"model-dialog\").close(); notice(); render();\n  });\n  $(\"choose-persona\").addEventListener(\"click\", () => {\n    fillSelect(\"persona-select\", options.personas, doc().source_persona_id || options.default_persona_id || options.personas[0]?.id, \"暂无人设\"); $(\"persona-dialog\").showModal();\n  });\n  async function loadPersona(id) {\n    const current = session(), mode = root.activeMode;\n    if (!id || working || generating() || root.pendingSave) return;\n    working = true; $(\"load-persona\").disabled = true; controls();\n    try {\n      const result = await api(\"GET\", \"designer/persona\", {id});\n      if (result.id !== id || typeof result.text !== \"string\") throw new Error(\"persona_designer_response_invalid\");\n      // Fetch first: a failed read must leave the previous design recoverable.\n      if (current.document.source_persona_id !== id) {\n        const document = newDocument(mode);\n        document.provider_id = current.document.provider_id;\n        document.source_persona_id = id; document.source_text = result.text;\n        root.sessions[mode] = {document};\n      } else {\n        current.document.source_text = result.text;\n      }\n      await persist(); $(\"persona-dialog\").close(); $(\"switch-persona-dialog\").close();\n      notice(\"已载入人设，可以先说说希望调整的地方。\"); render();\n    } catch (error) {\n      notice(errorText(error), true); $(\"persona-dialog\").close(); $(\"switch-persona-dialog\").close();\n    }\n    finally { working = false; $(\"load-persona\").disabled = !options.personas.length; controls(); }\n  }\n  $(\"persona-form\").addEventListener(\"submit\", event => {\n    event.preventDefault(); const id = $(\"persona-select\").value, d = doc();\n    if (!id || working || generating() || root.pendingSave) return;\n    const hasContent = d.messages.length || [\"source_text\", \"confirmed\", \"draft\", \"lorebook\", \"input\"].some(key => d[key].length);\n    if (id !== d.source_persona_id && hasContent) {\n      pendingPersonaId = id; $(\"persona-dialog\").close(); $(\"switch-persona-dialog\").showModal();\n    } else loadPersona(id);\n  });\n  $(\"confirm-persona-switch\").addEventListener(\"click\", () => loadPersona(pendingPersonaId));\n  $(\"switch-persona-dialog\").addEventListener(\"close\", () => { pendingPersonaId = \"\"; });\n  $(\"refresh-options\").addEventListener(\"click\", loadOptions); $(\"refresh-personas\").addEventListener(\"click\", loadOptions);\n  [\"save-draft\"].forEach(id => $(id).addEventListener(\"click\", openSave));\n  $(\"retry-save\").addEventListener(\"click\", () => saveSnapshot(root.retrySave));\n  $(\"save-form\").addEventListener(\"submit\", event => {\n    event.preventDefault(); const title = $(\"draft-title\").value.trim(); if (!title) return;\n    const snapshot = {id: uid(), title, state: copy(doc())}; $(\"save-dialog\").close(); saveSnapshot(snapshot);\n  });\n  $(\"open-drafts\").addEventListener(\"click\", () => { $(\"drafts-dialog\").showModal(); listDrafts(); });\n  $(\"more-drafts\").addEventListener(\"click\", () => listDrafts(nextBefore));\n  $(\"new-design\").addEventListener(\"click\", () => { $(\"drafts-dialog\").close(); $(\"reset-dialog\").showModal(); });\n  $(\"confirm-reset\").addEventListener(\"click\", () => {\n    if (generating() || root.pendingSave) { notice(\"请先等待本轮操作完成，再重新开始。\", true); $(\"reset-dialog\").close(); return; }\n    const provider = doc().provider_id;\n    root.sessions[root.activeMode] = {document: newDocument(root.activeMode)};\n    doc().provider_id = provider; persist(); $(\"reset-dialog\").close(); notice(); render();\n  });\n  $(\"copy-draft\").addEventListener(\"click\", () => copyText(\"draft-text\")); $(\"copy-lorebook\").addEventListener(\"click\", () => copyText(\"lorebook\"));\n  $(\"compare\").addEventListener(\"click\", () => {\n    $(\"compare-source\").textContent = doc().source_text; $(\"compare-draft\").textContent = doc().draft; $(\"compare-dialog\").showModal();\n  });\n  async function initialize() {\n    try {\n      bridge = window.AstrBotPluginPage;\n      const context = await bridge.ready();\n      entryMode = [\"create\", \"optimize\"].includes(context?.tab) ? context.tab : \"\";\n      const cached = await api(\"GET\", \"designer/client-state\", {});\n      root = cached.state?.version === 1 ? cached.state : fresh();\n      // Apply the entry after restoring memory; a bridge-generated click before\n      // the read finishes would otherwise overwrite or lose the selected mode.\n      if (entryMode) selectMode(entryMode);\n      document.querySelector(\".mode-switch\").hidden = !!entryMode;\n      await persist();\n      render(); await loadOptions();\n      if (session().error) notice(session().error, true);\n      await poll();\n    } catch (error) { notice(errorText(error), true); }\n  }\n  window.addEventListener(\"pagehide\", () => { disposed = true; clearTimeout(pollTimer); root = fresh(); render(); });\n  window.addEventListener(\"pageshow\", event => { if (event.persisted) { disposed = false; initialize(); } });\n  render(); initialize();\n})();\n</script></body>\n</html>\n\n\n";
